#include <string>
#include <unordered_set>

using namespace std;

class Solution {
public:
    int countPalindromicSubsequence(string s) {
        int res = 0;
        for (char c = 'a'; c <= 'z'; ++c) {
            int l = s.find(c), r = s.rfind(c);
            if (l < r) {
                unordered_set<char> mid(s.begin() + l + 1, s.begin() + r);
                res += mid.size();
            }
        }
        return res;
    }
};
